      ctx.fillStyle = '#334155'; ctx.strokeStyle = '#090d16'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(-7, 2); ctx.quadraticCurveTo(p.w * 0.5, -8, p.w + 7, 2); ctx.lineTo(p.w + 4, 6); ctx.lineTo(-4, 6); ctx.closePath(); ctx.fill(); ctx.stroke();
      ctx.restore();
