                ctx.quadraticCurveTo(px0 - 7, py0 - 11, px0 - 11, py0 - 14);
                ctx.quadraticCurveTo(px0 - 2, py0 - 13, px0 + 3.5, py0 + 1);
                ctx.closePath();
