                ctx.moveTo(midX + 2, fy);
                ctx.bezierCurveTo(midX - 15, fy - 7, midX - 28, fy - 1, midX - 36, fy + 8);
                ctx.quadraticCurveTo(midX - 24, fy + 5, midX - 2, fy + 4.2);
                ctx.closePath();
