      ctx.fillStyle = hG; ctx.strokeStyle = '#78350f'; ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(px + 4, py + 5);
      ctx.quadraticCurveTo(px + p.w * 0.5, py + 0.5 + flex, px + p.w - 4, py + 5);
