      ctx.fillStyle = '#8c7451'; ctx.strokeStyle = '#473824'; ctx.lineWidth = 1.2;
      ctx.fillRect(rStart, railY + 9, rEnd - rStart, 8); ctx.strokeRect(rStart, railY + 9, rEnd - rStart, 8);
      // Cast-iron flanged wheels with rotating spokes
