      ctx.fillStyle = '#5c3a21'; ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 2.2;
      ctx.beginPath(); ctx.arc(0, 0, 7.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.restore();
      return;
