      const bG = ctx.createLinearGradient(cx - 34, botY - 22, cx + 34, botY);
      bG.addColorStop(0, '#efe4cf'); bG.addColorStop(0.55, '#cbb591'); bG.addColorStop(1, '#856e4d');
