        ctx.fillStyle = '#c2410c'; ctx.strokeStyle = '#431407'; ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.roundRect(bx - 10, 18, 20, 15, [2, 2, 6, 6]); ctx.fill(); ctx.stroke();
        ctx.fillStyle = '#38bdf8';
