        const ox = bx + 270;
        ctx.save();
        ctx.translate(ox, groundY);

        // 1. Irregular Sculpted Wet-Sand & Lush Mossy Oasis Bank Rim
        const bankG = ctx.createLinearGradient(0, -24, 0, 14);
